steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(filter: {
        completedAt: { eq: \"2026-10-02\" },
        description: { contains: \"rollback window\" }
      }) {
        nodes {
          id
          identifier
          title
          description
          priority
          completedAt
          assignee {
            name
            id
          }
        }
      }
    }"
  }'
